/**
 * emit to subscription queries of type FindCorrectiveAction,
 * but only if the id matches
 *
 * @param		entity	CorrectiveAction
 */
	protected void emitFindCorrectiveAction( CorrectiveAction entity ) {
		LOGGER.info("handling emitFindCorrectiveAction" );
		
	    queryUpdateEmitter.emit(FindCorrectiveActionQuery.class,
	                            query -> query.getFilter().getCorrectiveActionId().equals(entity.getCorrectiveActionId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllCorrectiveAction
	 * 
	 * @param		entity	CorrectiveAction
	 */
	protected void emitFindAllCorrectiveAction( CorrectiveAction entity ) {
		LOGGER.info("handling emitFindAllCorrectiveAction" );
		
	    queryUpdateEmitter.emit(FindAllCorrectiveActionQuery.class,
	                            query -> true,
	                            entity);
	}

